<?php namespace App\Http\Controllers; use App\Http\Requests\ReminderRequest; use App\Models\Reminder; use Illuminate\Http\Request; class ReminderController extends Controller { public function index(Request $r){return $r->user()->reminders()->with('pet')->orderBy('due_at')->get();} public function store(ReminderRequest $r){$d=$r->validated(); if(!empty($d['pet_id']))abort_unless($r->user()->pets()->whereKey($d['pet_id'])->exists(),403);return Reminder::create($d+['user_id'=>$r->user()->id]);} public function update(ReminderRequest $r,Reminder $reminder){abort_unless($reminder->user_id===$r->user()->id,403);$reminder->update($r->validated());return $reminder;} public function complete(Request $r,Reminder $reminder){abort_unless($reminder->user_id===$r->user()->id,403);$reminder->update(['completed_at'=>now()]);return $reminder;} public function destroy(Request $r,Reminder $reminder){abort_unless($reminder->user_id===$r->user()->id,403);$reminder->delete();return response()->noContent();} }